import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import type { TeamPublicType, TeamType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    blockedHosts: string[]
    blockedIps: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    setBlockedHosts: (blockedHosts: string[]) => {
        blockedHosts: string[]
    }
    setBlockedIps: (blockedIps: string[]) => {
        blockedIps: string[]
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        blockedHosts: (currentTeam: TeamPublicType | TeamType | null) => string[]
        blockedIps: (currentTeam: TeamPublicType | TeamType | null) => string[]
    }
}

export type featureFlagRequestBlocklistLogicType = MakeLogicType<
    featureFlagRequestBlocklistLogicValues,
    featureFlagRequestBlocklistLogicActions,
    Record<string, any>,
    featureFlagRequestBlocklistLogicMeta
>

export const featureFlagRequestBlocklistLogic = kea<featureFlagRequestBlocklistLogicType>([
    path(['products', 'feature_flags', 'frontend', 'featureFlagRequestBlocklistLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        setBlockedHosts: (blockedHosts: string[]) => ({ blockedHosts }),
        setBlockedIps: (blockedIps: string[]) => ({ blockedIps }),
    }),
    selectors({
        blockedHosts: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_hosts ?? [],
        ],
        blockedIps: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_ips ?? [],
        ],
    }),
    listeners(({ actions }) => ({
        // Send only the edited list. The API keeps a list the request leaves out, so a save
        // here does not overwrite a newer change to the other list with the value this page loaded.
        setBlockedHosts: ({ blockedHosts }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_hosts: blockedHosts } })
        },
        setBlockedIps: ({ blockedIps }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_ips: blockedIps } })
        },
    })),
])
